CREATE TABLE IF NOT EXISTS `#__decarofinance_budgets` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`title` VARCHAR(255) NOT NULL,`period_start` DATE NULL,`period_end` DATE NULL,`state` TINYINT NOT NULL DEFAULT 1,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),KEY `idx_state` (`state`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_budget_lines` (`id` INT UNSIGNED NOT NULL AUTO_INCREMENT,`budget_id` INT UNSIGNED NOT NULL,`kind` VARCHAR(16) NOT NULL,`title` VARCHAR(255) NOT NULL,`planned_amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (`id`),KEY `idx_budget` (`budget_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_obligations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`kind` VARCHAR(64) NOT NULL,`description` VARCHAR(500) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`due_date` DATE NULL,`status` VARCHAR(32) NOT NULL DEFAULT 'open',`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_source` (`source_component`,`source_entity`,`source_id`),KEY `idx_status_due` (`status`,`due_date`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_payments` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`paid_at` DATETIME NULL,`method` VARCHAR(64) NULL,`reference` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_payment_allocations` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`payment_id` BIGINT UNSIGNED NOT NULL,`obligation_id` BIGINT UNSIGNED NOT NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,PRIMARY KEY (`id`),UNIQUE KEY `uq_payment_obligation` (`payment_id`,`obligation_id`),KEY `idx_obligation` (`obligation_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_deposit_accounts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`owner_component` VARCHAR(100) NOT NULL,`owner_entity` VARCHAR(100) NOT NULL,`owner_id` VARCHAR(191) NOT NULL,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`state` TINYINT NOT NULL DEFAULT 1,PRIMARY KEY (`id`),UNIQUE KEY `uq_owner_currency` (`owner_component`,`owner_entity`,`owner_id`,`currency`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_deposit_movements` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`account_id` BIGINT UNSIGNED NOT NULL,`external_key` VARCHAR(191) NULL,`movement_type` VARCHAR(32) NOT NULL,`amount` DECIMAL(15,2) NOT NULL,`description` VARCHAR(500) NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`created` DATETIME NOT NULL,`created_by` INT UNSIGNED NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_account_created` (`account_id`,`created`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS `#__decarofinance_transactions` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,`external_key` VARCHAR(191) NULL,`direction` VARCHAR(16) NOT NULL,`amount` DECIMAL(15,2) NOT NULL DEFAULT 0.00,`currency` CHAR(3) NOT NULL DEFAULT 'EUR',`occurred_at` DATETIME NOT NULL,`source_component` VARCHAR(100) NULL,`source_entity` VARCHAR(100) NULL,`source_id` VARCHAR(191) NULL,`description` VARCHAR(500) NULL,PRIMARY KEY (`id`),UNIQUE KEY `uq_external_key` (`external_key`),KEY `idx_occurred` (`occurred_at`),KEY `idx_source` (`source_component`,`source_entity`,`source_id`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 DEFAULT COLLATE=utf8mb4_unicode_ci;
